import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import 'app.dart';
import 'firebase_options.dart';

/// Entry point.
///
/// 1. `ensureInitialized` lets us call platform code before `runApp`.
/// 2. `Firebase.initializeApp` connects to the `student-life-1` project using
///    the settings generated by `flutterfire configure`.
/// 3. `ProviderScope` is the container that stores every Riverpod provider's
///    state; it must wrap the whole app.
Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  runApp(const ProviderScope(child: CampusCareApp()));
}
